action.query:
query GetWorkcenter($where: WorkcenterWhereInput) {
  query: workcenter(where: $where) {
    edges {
      node {
        id
        name
        isActive
        code
        description
        cellId
        cell {
          id
          code
          name
        }
        currentWorkOrderId
        currentWorkOrder {
          id
          code
        }
        lineId
        line {
          id
          code
          name
        }
        createdAt
        createdByUser {
          id
          firstName
          lastName
        }
      }
    }
  }
}

