dataTransform.transform:
[edges.node~>|$|{
  "createdByDisplay": createdByUser != null ? createdByUser.firstName & ' ' & createdByUser.lastName : "",
  "activeColor": isActive = true ? "#2e7d32" : "#d32f2f",
  "activeDisplay": isActive = true ? "Active" : "Inactive",
  "modeColor": currentModeId != null ? (
    currentModeId = "Production" ? "#2e7d32" : (currentModeId = "idle" ? "#ed6c02" : (currentModeId = "disabled" ? "#d32f2f" : "#757575"))
  ) : "#757575",
  "stateColor": currentStateId != null ? (
    currentStateId = "running" ? "#2e7d32" : (currentStateId = "stopped" ? "#757575" : (currentStateId = "held" ? "#ed6c02" : (currentStateId = "blocked" ? "#d32f2f" : (currentStateId = "starved" ? "#ed6c02" : (currentStateId = "faulted" ? "#d32f2f" : "#757575")))))
  ) : "#757575"
}|]

